create table if not exists content_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,publish_at timestamptz,title text not null,pillar text,platform text not null default 'LinkedIn',format text,hook text,key_points text,cta text,purpose text,estimated_minutes int not null default 30,status text not null default 'Idea',url text,notes text,created_at timestamptz not null default now());
create table if not exists sales_activities(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,lead_id uuid references leads(id) on delete cascade,activity_type text not null,occurred_at timestamptz not null default now,note text,next_follow_up date);
create table if not exists opportunities(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,lead_id uuid references leads(id) on delete cascade,name text not null,value numeric not null default 0,stage text not null default 'New',probability numeric not null default 0,expected_close date,created_at timestamptz not null default now());
alter table content_items enable row level security;alter table sales_activities enable row level security;alter table opportunities enable row level security;
create policy content_self on content_items for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy sales_activity_self on sales_activities for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy opportunities_self on opportunities for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create index if not exists tasks_user_due on tasks(user_id,due_at);create index if not exists leads_user_followup on leads(user_id,next_follow_up);create index if not exists transactions_user_date on transactions(user_id,occurred_on);create index if not exists content_user_publish on content_items(user_id,publish_at);